card:g4971.last:
{
  "nl": {
    "issue": [
      {
        "text": "标的物数量或质量不符合约定时，买受人的检验通知义务、通知期间及“视为符合约定”的效果（第621条）",
        "rules": ["c621-1", "c621-1b", "c621-2", "c621-2b", "c621-2y", "c621-warranty", "c621-3"]
      },
      {
        "text": "分期付款买卖中买受人未付到期价款达五分之一时出卖人的救济（第634条）",
        "rules": ["c634-1a", "c634-1b", "c634-2", "c634-3"]
      },
      {
        "text": "凭样品买卖的样品封存、质量标准，以及样品有隐蔽瑕疵时的处理（第635、636条）",
        "rules": ["c635-1", "c635-1b", "c635-2", "c636"]
      },
      {
        "text": "试用买卖中买受人购买意思表示的认定（第638条）",
        "rules": ["c638-1a", "c638-1b", "c638-2"]
      },
      {
        "text": "所有权保留的效力、出卖人取回权及其限制、买受人回赎权与未回赎的后果（第641–643条）",
        "rules": ["c641-1", "c641-1b", "c641-2", "c641-2b", "c642-1", "c642-75", "c642-third", "c642-2", "c642-3", "c643-1", "c643-2", "c643-3", "c643-4"]
      }
    ],
    "conditions": [
      {
        "text": "当事人约定检验期限的，买受人应当在检验期限内通知；没有约定检验期限的，应当在发现或者应当发现不符合约定的合理期限内通知出卖人",
        "rules": ["c621-1", "c621-2"]
      },
      {
        "text": "分期付款买卖中，买受人未支付到期价款的数额达到全部价款的五分之一，且经催告后在合理期限内仍未支付",
        "rules": ["c634-1a", "c634-1b"]
      },
      {
        "text": "凭样品买卖的当事人应当封存样品，并可以对样品质量予以说明",
        "rules": ["c635-1", "c635-1b"]
      },
      {
        "text": "凭样品买卖的买受人不知道样品有隐蔽瑕疵",
        "rules": ["c636"]
      },
      {
        "text": "试用期限届满，买受人对是否购买未作表示；或者试用期内已支付部分价款、对标的物实施出卖、出租、设立担保物权等行为",
        "rules": ["c638-1b", "c638-2"]
      },
      {
        "text": "约定出卖人保留标的物所有权且所有权尚未转移；买受人未按约支付价款经催告后合理期限内仍未支付、未完成特定条件，或将标的物出卖、出质或作其他不当处分，并造成出卖人损害",
        "rules": ["c641-1", "c642-1"]
      },
      {
        "text": "出卖人取回标的物后，买受人在双方约定或者出卖人指定的合理回赎期限内消除取回的事由",
        "rules": ["c643-1"]
      }
    ],
    "exceptions": [
      {
        "text": "对标的物有质量保证期的，适用质量保证期，不适用自收到标的物之日起二年的通知期间",
        "rules": ["c621-warranty", "c621-2y"]
      },
      {
        "text": "出卖人知道或者应当知道提供的标的物不符合约定的，买受人不受前两款通知时间的限制",
        "rules": ["c621-3"]
      },
      {
        "text": "取回权以“除当事人另有约定外”为限，当事人另有约定的从其约定",
        "rules": ["c642-1"]
      },
      {
        "text": "买受人已支付标的物总价款的百分之七十五以上，或者第三人已善意取得标的物所有权或其他物权的，出卖人不得主张取回（司法解释、笔记）",
        "rules": ["c642-75", "c642-third"]
      }
    ],
    "effects": [
      {
        "text": "买受人怠于通知、在合理期限内未通知或者自收到标的物之日起二年内未通知的，视为标的物的数量或者质量符合约定",
        "rules": ["c621-1b", "c621-2b", "c621-2y"]
      },
      {
        "text": "出卖人可以请求买受人支付全部价款，或者解除合同；解除合同的，可以请求买受人支付标的物的使用费",
        "rules": ["c634-1a", "c634-1b", "c634-2"]
      },
      {
        "text": "出卖人解除合同并扣留已受领价金，扣留金额超过标的物使用费及标的物受损赔偿额的，买受人有权请求返还超过部分（司法解释）",
        "rules": ["c634-3"]
      },
      {
        "text": "出卖人交付的标的物应当与样品及其说明的质量相同；样品有隐蔽瑕疵而买受人不知的，交付的标的物仍应当符合同种物的通常标准",
        "rules": ["c635-2", "c636"]
      },
      {
        "text": "试用期内买受人可以购买也可以拒绝购买；期限届满未作表示，或者试用期内支付部分价款、处分标的物的，视为购买（同意购买）",
        "rules": ["c638-1a", "c638-1b", "c638-2"]
      },
      {
        "text": "可以约定买受人未履行支付价款或其他义务时标的物所有权属于出卖人；该保留的所有权未经登记不得对抗善意第三人，已登记则可以对抗",
        "rules": ["c641-1", "c641-1b", "c641-2", "c641-2b"]
      },
      {
        "text": "出卖人有权取回标的物；可以与买受人协商取回，协商不成的可以参照适用担保物权的实现程序",
        "rules": ["c642-1", "c642-2", "c642-3"]
      },
      {
        "text": "买受人可以请求回赎标的物；未回赎的，出卖人可以合理价格将标的物出卖给第三人，所得价款扣除未付价款及必要费用后有剩余的应当返还买受人，不足部分由买受人清偿",
        "rules": ["c643-1", "c643-2", "c643-3", "c643-4"]
      }
    ],
    "priority": [
      {
        "text": "质量保证期优先于第621条第2款自收到标的物之日起二年的通知期间",
        "rules": ["c621-warranty", "c621-2y"]
      },
      {
        "text": "出卖人知道或者应当知道标的物不符合约定时，通知期间的限制不发生“视为符合约定”的效果",
        "rules": ["c621-3"]
      },
      {
        "text": "样品有隐蔽瑕疵且买受人不知情时，同种物的通常标准优先于“与样品相同”的标准",
        "rules": ["c636", "c635-2"]
      },
      {
        "text": "买受人已付总价款百分之七十五以上或者第三人已善意取得时，取回权被排除",
        "rules": ["c642-75", "c642-third", "c642-1"]
      }
    ],
    "distinguish": [
      {
        "text": "笔记：分期付款买卖须将总价款在一定期间内至少分三次支付，可适用于动产与不动产；而所有权保留只能适用于动产（不动产须登记）",
        "rules": []
      },
      {
        "text": "笔记：分期付款买卖中当事人可以约定所有权和风险承担的转移时间，没有约定的为标的物交付之日；法条未规定，属学理补充",
        "rules": []
      },
      {
        "text": "LEGO 卡片称第634条为特别规则、优先于一般合同解除权，并称与第642条取回权并行；该优先关系法条未明定，仅供参考",
        "rules": []
      },
      {
        "text": "第632条（单物质量瑕疵致合同目的不能实现）、第633条（分批交付的解除）与本行的分期付款、凭样品、试用买卖规则适用对象不同",
        "rules": []
      }
    ]
  },
